    <title>Image Preview</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #090d16;
        --panel: #111827;
        --panel-strong: #182235;
        --text: #f8fafc;
        --muted: #bac6d8;
        --line: #334155;
        --accent: #8b5cf6;
        --accent-strong: #a78bfa;
        --danger: #f43f5e;
        --danger-strong: #fb7185;
        --shadow: 0 30px 80px rgb(0 0 0 / 0.55);
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        color: var(--text);
        background:
          radial-gradient(circle at top left, rgb(139 92 246 / 0.28), transparent 36rem),
          radial-gradient(circle at bottom right, rgb(244 63 94 / 0.18), transparent 32rem),
          var(--bg);
      }

      .skip-link {
        position: fixed;
        inset-block-start: 1rem;
        inset-inline-start: 1rem;
        z-index: 10;
        transform: translateY(-180%);
        border-radius: 999px;
        padding: 0.7rem 1rem;
        color: #111827;
        background: #f8fafc;
        font-weight: 700;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .shell {
        width: min(1120px, calc(100% - 2rem));
        margin-inline: auto;
        padding: 2rem 0 4rem;
      }

      header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        margin-block-end: 2rem;
      }

      .brand {
        display: inline-flex;
        align-items: center;
        gap: 0.75rem;
        color: var(--muted);
        font-weight: 700;
        letter-spacing: 0.02em;
      }

      .brand-mark {
        display: grid;
        width: 2.5rem;
        height: 2.5rem;
        place-items: center;
        border: 1px solid rgb(255 255 255 / 0.16);
        border-radius: 0.85rem;
        color: var(--accent-strong);
        background: rgb(255 255 255 / 0.06);
      }

      main {
        display: grid;
        min-height: calc(100vh - 9rem);
        place-items: center;
      }

      .preview-card {
        width: min(100%, 760px);
        overflow: hidden;
        border: 1px solid rgb(255 255 255 / 0.12);
        border-radius: 2rem;
        background: linear-gradient(145deg, rgb(17 24 39 / 0.96), rgb(15 23 42 / 0.88));
        box-shadow: var(--shadow);
      }

      .image-frame {
        position: relative;
        aspect-ratio: 16 / 10;
        overflow: hidden;
        background: #0f172a;
      }

      .image-frame img {
        display: block;
        width: 100%;
        height: 100%;
        object-fit: cover;
      }

      .image-frame::after {
        position: absolute;
        inset: 0;
        content: "";
        background: linear-gradient(to top, rgb(9 13 22 / 0.8), transparent 42%);
        pointer-events: none;
      }

      .image-badge {
        position: absolute;
        inset-block-start: 1rem;
        inset-inline-start: 1rem;
        z-index: 1;
        border: 1px solid rgb(255 255 255 / 0.2);
        border-radius: 999px;
        padding: 0.45rem 0.75rem;
        color: var(--text);
        background: rgb(15 23 42 / 0.72);
        font-size: 0.85rem;
        font-weight: 700;
        backdrop-filter: blur(12px);
      }

      .preview-content {
        display: grid;
        gap: 1.25rem;
        padding: clamp(1.25rem, 4vw, 2rem);
      }

      .eyebrow {
        margin: 0 0 0.45rem;
        color: var(--accent-strong);
        font-size: 0.78rem;
        font-weight: 800;
        letter-spacing: 0.16em;
        text-transform: uppercase;
      }

      h1,
      h2,
      p {
        margin-block-start: 0;
      }

      h1 {
        margin-block-end: 0.65rem;
        font-size: clamp(2rem, 6vw, 4rem);
        line-height: 0.95;
        letter-spacing: -0.06em;
      }

      .description {
        max-width: 62ch;
        margin-block-end: 0;
        color: var(--muted);
        font-size: 1.03rem;
        line-height: 1.7;
      }

      .actions {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        gap: 0.85rem;
      }

      button {
        min-height: 44px;
        border: 0;
        border-radius: 999px;
        padding: 0.78rem 1.05rem;
        color: var(--text);
        background: var(--panel-strong);
        font: inherit;
        font-weight: 800;
        cursor: pointer;
        transition:
          transform 160ms ease,
          border-color 160ms ease,
          background-color 160ms ease,
          box-shadow 160ms ease;
      }

      button:hover {
        transform: translateY(-1px);
      }

      button:focus-visible,
      .skip-link:focus-visible {
        outline: 3px solid #f8fafc;
        outline-offset: 4px;
        box-shadow: 0 0 0 7px rgb(139 92 246 / 0.45);
      }

      .trigger {
        border: 1px solid rgb(244 63 94 / 0.45);
        background: linear-gradient(135deg, #9f1239, var(--danger));
        box-shadow: 0 16px 38px rgb(244 63 94 / 0.28);
      }

      .secondary-action {
        border: 1px solid rgb(255 255 255 / 0.12);
      }

      .status {
        min-height: 1.5rem;
        color: var(--danger-strong);
        font-weight: 700;
      }

      dialog {
        width: min(92vw, 460px);
        max-height: min(86vh, 560px);
        overflow: auto;
        border: 1px solid rgb(255 255 255 / 0.16);
        border-radius: 1.5rem;
        padding: 0;
        color: var(--text);
        background: linear-gradient(160deg, #151f32, #0f172a);
        box-shadow: var(--shadow);
      }

      dialog::backdrop {
        background:
          radial-gradient(circle at 50% 22%, rgb(139 92 246 / 0.2), transparent 24rem),
          rgb(2 6 23 / 0.78);
        backdrop-filter: blur(7px);
      }

      .dialog-panel {
        display: grid;
        gap: 1.25rem;
        padding: clamp(1.25rem, 5vw, 2rem);
      }

      .dialog-icon {
        display: grid;
        width: 3rem;
        height: 3rem;
        place-items: center;
        border: 1px solid rgb(244 63 94 / 0.3);
        border-radius: 1rem;
        color: #fecdd3;
        background: rgb(244 63 94 / 0.12);
        font-size: 1.3rem;
      }

      .dialog-copy h2 {
        margin-block-end: 0.55rem;
        font-size: clamp(1.45rem, 5vw, 2rem);
        line-height: 1.1;
        letter-spacing: -0.04em;
      }

      .dialog-copy p {
        margin-block-end: 0;
        color: var(--muted);
        line-height: 1.65;
      }

      .dialog-actions {
        display: flex;
        flex-direction: row-reverse;
        flex-wrap: wrap;
        gap: 0.75rem;
      }

      .danger-action {
        background: linear-gradient(135deg, #be123c, #e11d48);
      }

      .cancel-action {
        border: 1px solid rgb(255 255 255 / 0.14);
        background: rgb(255 255 255 / 0.08);
      }

      @media (max-width: 520px) {
        header {
          align-items: flex-start;
          flex-direction: column;
        }

        .actions,
        .dialog-actions,
        .actions button,
        .dialog-actions button {
          width: 100%;
        }
      }

      @media (prefers-reduced-motion: reduce) {
        *,
        *::before,
        *::after {
          scroll-behavior: auto !important;
          transition-duration: 0.01ms !important;
        }
      }

      @media (forced-colors: active) {
        body,
        .preview-card,
        dialog {
          background: Canvas;
        }

        button,
        .trigger,
        .secondary-action,
        .cancel-action,
        .danger-action {
          border: 1px solid ButtonBorder;
          color: ButtonText;
          background: ButtonFace;
          box-shadow: none;
        }

        button:focus-visible,
        .skip-link:focus-visible {
          outline: 3px solid Highlight;
          box-shadow: none;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="app"></div>

    <script>
      const image = {
        title: "Midnight lake",
        description:
          "A quiet mountain lake photographed after sunset, saved in your private image library.",
        src:
          "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1280 800'%3E%3Cdefs%3E%3ClinearGradient id='sky' x1='0' x2='0' y1='0' y2='1'%3E%3Cstop stop-color='%231d2b53'/%3E%3Cstop offset='0.58' stop-color='%232b5876'/%3E%3Cstop offset='1' stop-color='%230b1020'/%3E%3C/linearGradient%3E%3ClinearGradient id='lake' x1='0' x2='0' y1='0' y2='1'%3E%3Cstop stop-color='%232d6f8f'/%3E%3Cstop offset='1' stop-color='%2307101f'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='1280' height='800' fill='url(%23sky)'/%3E%3Ccircle cx='1020' cy='155' r='88' fill='%23f4e8c1'/%3E%3Cpath d='M0 430 175 250l130 118 170-195 225 257 140-132 148 132 128-110 164 110v370H0z' fill='%23060b18'/%3E%3Cpath d='M0 486h1280v314H0z' fill='url(%23lake)'/%3E%3Cpath d='M100 584c190-42 303-42 493 0s302 42 493 0' fill='none' stroke='%2389c2d9' stroke-opacity='.45' stroke-width='12'/%3E%3Cpath d='M165 660c156-27 249-27 405 0s249 27 405 0' fill='none' stroke='%23c4b5fd' stroke-opacity='.3' stroke-width='8'/%3E%3C/svg%3E",
        alt: "Moonlit mountain lake with dark peaks reflected in the water"
      };

      function Header() {
        return `
          <header class="site-header">
            <div class="brand" aria-label="Lumina Library">
              <span class="brand-mark" aria-hidden="true">L</span>
              <span>Lumina Library</span>
            </div>
          </header>
        `;
      }

      function ImagePreview({ title, description, src, alt }) {
        return `
          <article class="preview-card" aria-labelledby="image-title">
            <div class="image-frame">
              <img src="${src}" alt="${alt}">
              <span class="image-badge">Image preview</span>
            </div>
            <div class="preview-content">
              <div>
                <p class="eyebrow">Library item</p>
                <h1 id="image-title">${title}</h1>
                <p class="description">${description}</p>
              </div>
              <div class="actions">
                <button class="trigger" type="button" aria-haspopup="dialog">
                  Delete image
                </button>
                <button class="secondary-action" type="button">
                  Keep in library
                </button>
              </div>
              <p class="status" aria-live="polite"></p>
            </div>
          </article>
        `;
      }

      function DeleteDialog({ title }) {
        return `
          <dialog
            id="delete-dialog"
            aria-labelledby="dialog-title"
            aria-describedby="dialog-description"
          >
            <div class="dialog-panel">
              <div class="dialog-icon" aria-hidden="true">!</div>
              <div class="dialog-copy">
                <h2 id="dialog-title">Delete this image?</h2>
                <p id="dialog-description">
                  "${title}" will be removed from your library. This action cannot be undone.
                </p>
              </div>
              <div class="dialog-actions">
                <button class="danger-action" type="button" data-confirm-delete>
                  Delete image
                </button>
                <button class="cancel-action" type="button" data-cancel-delete autofocus>
                  Cancel
                </button>
              </div>
            </div>
          </dialog>
        `;
      }

      function App() {
        return `
          <div class="shell">
            ${Header()}
            <main id="main-content">
              ${ImagePreview(image)}
            </main>
          </div>
          ${DeleteDialog(image)}
        `;
      }

      document.getElementById("app").innerHTML = App();

      const dialog = document.getElementById("delete-dialog");
      const trigger = document.querySelector(".trigger");
      const cancelButton = dialog.querySelector("[data-cancel-delete]");
      const confirmButton = dialog.querySelector("[data-confirm-delete]");
      const status = document.querySelector(".status");

      trigger.addEventListener("click", () => {
        dialog.showModal();
      });

      cancelButton.addEventListener("click", () => {
        dialog.close("cancel");
      });

      confirmButton.addEventListener("click", () => {
        status.textContent = "Image deleted from your library.";
        dialog.close("delete");
      });
    </script>
  </body>
</html>
